int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags)
{
    int result = -EINVAL;
    struct sock *sk = sock->sk;
    struct net *net = sock_net(sk);
    struct pptp_channel *channel = NULL;
    struct sockaddr_pptp addr;
    int mtu;

    if (!sock || !uservaddr || sockaddr_len < sizeof(struct sockaddr_pptp))
        return -EINVAL;

    if (sk->sk_state != TCP_CLOSE)
        return -EISCONN;

    if (sk->sk_state == TCP_CLOSE_WAIT)
        return -EINVAL;

    sock_hold(sk);

    sk->sk_state = TCP_SYN_SENT;

    memcpy(&addr, uservaddr, sizeof(addr));
    addr.sa_family = AF_INET;
    addr.addr.sin_family = AF_INET;

    mtu = sock->sk->sk_route_caps & ~IPOPT_ALLFRAG;
    if (mtu > 1500)
        mtu = 1500;
    sock->sk->sk_route_caps = mtu;

    channel = pptp_channel_alloc(net, addr.addr.sin_addr, addr.call_id, GFP_KERNEL);
    if (!channel) {
        result = -ENOMEM;
        goto out;
    }

    result = ppp_register_net_channel(channel);
    if (result < 0)
        goto out_free_channel;

    sk->sk_state = TCP_ESTABLISHED;
    result = 0;

out_free_channel:
    if (result < 0)
        pptp_channel_free(channel);
out:
    sock_put(sk);
    return result;
}

int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags) {
    int result = -EINVAL;

    if (!sock || !uservaddr || sockaddr_len <= 0) {
        return -EINVAL;
    }

    if (uservaddr->sa_family != AF_INET) {
        return -EAFNOSUPPORT;
    }

    lock_sock(sock);
    if (sock->sk->sk_state != TCP_CLOSE && sock->sk->sk_state != TCP_ESTABLISHED) {
        release_sock(sock);
        return -EALREADY;
    }

    result = setup_pptp_channel(sock, uservaddr, sockaddr_len, flags);
    if (result < 0) {
        release_sock(sock);
        return result;
    }

    adjust_mtu(sock);
    register_ppp_channel(sock);
    sock->sk->sk_state = TCP_ESTABLISHED;
    release_sock(sock);

    return 0;
}

int establish_pptp_connection(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags) {
    int result = -EINVAL;

    if (!sock || !uservaddr) {
        return -EINVAL;
    }

    if (sockaddr_len < sizeof(struct sockaddr)) {
        return -EINVAL;
    }

    if (uservaddr->sa_family != AF_INET) {
        return -EAFNOSUPPORT;
    }

    sock->sk->sk_state = TCP_ESTABLISHED;
    lock_sock(sock->sk);

    if (sock->sk->sk_state != TCP_ESTABLISHED || sock_is_dead(sock)) {
        release_sock(sock->sk);
        return -EINVAL;
    }

    result = setup_pptp_channel(sock, uservaddr);
    if (result < 0) {
        release_sock(sock->sk);
        return result;
    }

    result = route_pptp_output(sock, uservaddr);
    if (result < 0) {
        release_sock(sock->sk);
        return result;
    }

    adjust_mtu(sock);
    register_ppp_channel(sock);

    sock->sk->sk_state = TCP_CLOSE;
    release_sock(sock->sk);

    return result;
}

