int pptp_connect(struct socket *sock, struct sockaddr *uservaddr, int sockaddr_len, int flags)
{
    int result = -EINVAL;
    struct sock *sk = sock->sk;
    struct net_device *dev;
    int mtu;

    if (!sock || !uservaddr || sockaddr_len < sizeof(struct sockaddr_in))
        return -EINVAL;

    if (((struct sockaddr_in *)uservaddr)->sin_family != AF_INET)
        return -EPROTONOSUPPORT;

    lock_sock(sk);

    if (sk->sk_state != TCP_CLOSE && sk->sk_state != TCP_ESTABLISHED) {
        release_sock(sk);
        return -EISCONN;
    }

    dev = dev_get_by_name("ppp0");
    if (!dev) {
        release_sock(sk);
        return -ENODEV;
    }

    mtu = dev->mtu;
    if (mtu > 1500)
        mtu = 1500;

    sock_set_flag(sk, SOCK_ZAPPED);
    sk->sk_state = TCP_ESTABLISHED;

    result = register_ppp_channel(sk, dev, mtu);
    if (result < 0) {
        sk->sk_state = TCP_CLOSE;
        sock_reset_flag(sk, SOCK_ZAPPED);
    }

    release_sock(sk);
    return result;
}
